/* Templates / knowledge / tasks / settings pages — extracted from app.js (ADR-0002 domain split).
 * Loaded after shared.js; infra and state resolve through window. */
const {state,api,esc,fmt,toast,modal,modalWide,closeModal,$}=window;
window.templatesPage=templatesPage;window.knowledgePage=knowledgePage;window.tasksPage=tasksPage;window.settingsPage=settingsPage;

async function templatesPage(){await window.ensureProjects();const d=await api('/api/v1/templates');$('#content').innerHTML=window.head('岗位模板','模板应保存可复用的标准定义，并能够从项目生成、编辑及应用到新项目。',`<button class="btn" onclick="saveCurrentAsTemplate()">从当前项目保存模板</button><button class="btn primary" onclick="openTemplate()">＋ 新建模板</button>`)+`<section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>模板</th><th>岗位</th><th>标准数</th><th>更新</th><th></th></tr></thead><tbody>${d.templates.length?d.templates.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.role_title)}</td><td>${x.payload?.criteria?.length||0}</td><td>${new Date(x.updated_at).toLocaleString()}</td><td class="right"><button class="btn small" onclick='editTemplate(${JSON.stringify(JSON.stringify(x)).replace(/'/g,"&#39;")})'>编辑模板</button> <button class="btn small primary" onclick="applyTemplate('${x.template_id}')">应用到项目</button> <button class="btn small danger" onclick="deleteTemplate('${x.template_id}')">删除</button></td></tr>`).join(''):'<tr><td colspan="5"><div class="empty"><strong>暂无模板</strong>可从成熟项目保存完整标准模板。</div></td></tr>'}</tbody></table></div></section>`}
window.openTemplate=()=>modal('新建岗位模板',`<div class="form-grid"><div class="field"><label>模板名称</label><input id="t-name" class="input"></div><div class="field"><label>岗位名称</label><input id="t-role" class="input"></div><div class="field full"><label>标准（每行一个）</label><textarea id="t-criteria" class="textarea" placeholder="战略分析\n跨团队协同\n数据能力"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveTemplate()">保存模板</button>`);
window.saveTemplate=async()=>{const criteria=$('#t-criteria').value.split(/\n+/).map(x=>x.trim()).filter(Boolean).map(name=>({name,decision_critical:false,verification_required:true,verification_probes:[],assessment_stages:[{stage_key:'resume',required:true}]}));try{await api('/api/v1/templates',{method:'POST',body:JSON.stringify({name:$('#t-name').value,role_title:$('#t-role').value,payload:{criteria}})});closeModal();toast('模板已保存');await templatesPage()}catch(e){toast(e.message,true)}};
window.editTemplate=s=>{const x=JSON.parse(s);modal('编辑模板',`<div class="form-grid"><div class="field"><label>模板名称</label><input id="te-name" class="input" value="${esc(x.name)}"></div><div class="field"><label>岗位名称</label><input id="te-role" class="input" value="${esc(x.role_title)}"></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="updateTemplate('${x.template_id}')">保存修改</button>`)};
window.updateTemplate=async id=>{await api(`/api/v1/templates/${id}`,{method:'PATCH',body:JSON.stringify({name:$('#te-name').value,role_title:$('#te-role').value})});closeModal();toast('模板已更新');await templatesPage()};
window.applyTemplate=async id=>{await window.ensureProjects();if(!state.projects.length)return toast('请先创建招聘项目',true);modal('应用模板到项目',`<div class="field"><label>目标项目</label><select id="ta-project" class="select">${window.projectOptions()}</select></div><p class="subtle">默认使用 merge，仅补充尚不存在的 Criteria，不覆盖当前编辑内容。</p>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="confirmApplyTemplate('${id}')">应用模板</button>`)};
window.confirmApplyTemplate=async id=>{const pid=$('#ta-project').value;await api(`/api/v1/templates/${id}/apply/${pid}`,{method:'POST',body:JSON.stringify({mode:'merge'})});closeModal();toast('模板已应用到项目标准草案')};
window.saveCurrentAsTemplate=async()=>{await window.ensureProjects();if(!state.projects.length)return toast('没有可保存的项目',true);modal('从当前项目保存模板',`<div class="field"><label>项目</label><select id="ts-project" class="select">${window.projectOptions()}</select></div><div class="field" style="margin-top:10px"><label>模板名称</label><input id="ts-name" class="input" placeholder="例如：产品经理标准模板"></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="confirmSaveCurrentTemplate()">保存</button>`)};
window.confirmSaveCurrentTemplate=async()=>{const pid=$('#ts-project').value;await api(`/api/v1/projects/${pid}/templates/from-current`,{method:'POST',body:JSON.stringify({name:$('#ts-name').value})});closeModal();toast('已从当前项目保存模板');await templatesPage()};
window.deleteTemplate=async id=>{if(confirm('删除该模板？')){await api(`/api/v1/templates/${id}`,{method:'DELETE'});await templatesPage()}};
async function knowledgePage(){await window.ensureProjects();const s=await api('/api/v1/knowledge/status');$('#content').innerHTML=window.head('知识库','知识不仅用于检索，也可以把岗位/能力建议直接送入当前项目的标准草案。')+`<div class="grid kpi" style="grid-template-columns:repeat(5,1fr)">${s.databases.map(x=>`<div class="kpi-card"><div class="kpi-label">${esc(x.name)}</div><div class="kpi-value" style="font-size:18px">${x.available?'可用':'缺失'}</div><div class="kpi-note">${x.available?`${(x.size_bytes/1024/1024).toFixed(1)} MB`:'未装配'}</div></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>知识检索与应用</h2></div><div class="panel-body"><div class="searchbar"><input id="k-q" class="input" placeholder="岗位、能力、市场关键词"><button class="btn primary" onclick="knowledgeSearch()">搜索</button></div><div id="k-results" style="margin-top:14px"><div class="empty">输入关键词开始检索。</div></div></div></section>`}
window.knowledgeSearch=async()=>{try{const d=await api(`/api/v1/knowledge/search?q=${encodeURIComponent($('#k-q').value)}&limit=20`);state.knowledgeResults=d.results||[];$('#k-results').innerHTML=d.results.length?`<div class="quick-list">${d.results.map((x,i)=>`<div class="quick-item"><div><div class="quick-title">${esc(x.title)}</div><div class="quick-note">${esc(x.database)} · ${esc(x.detail)}</div></div><button class="btn small primary" onclick="applyKnowledge(${i})">应用到项目标准草案</button></div>`).join('')}</div>`:'<div class="empty">没有找到匹配结果。</div>'}catch(e){toast(e.message,true)}};
window.applyKnowledge=async i=>{await window.ensureProjects();if(!state.projects.length)return toast('请先创建招聘项目',true);const x=state.knowledgeResults[i];modal('应用知识建议',`<div class="field"><label>目标项目</label><select id="ka-project" class="select">${window.projectOptions()}</select></div><div class="field" style="margin-top:10px"><label>Criterion 名称</label><input id="ka-name" class="input" value="${esc(x.title)}"></div><label class="check"><input id="ka-critical" type="checkbox"> 设为决策关键条件</label>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="confirmApplyKnowledge(${i})">应用</button>`)};
window.confirmApplyKnowledge=async i=>{const x=state.knowledgeResults[i];const pid=$('#ka-project').value;await api(`/api/v1/projects/${pid}/knowledge/apply`,{method:'POST',body:JSON.stringify({result:x,criterion_name:$('#ka-name').value,decision_critical:$('#ka-critical').checked,verification_required:true})});closeModal();toast('知识建议已应用到项目标准草案')};
async function tasksPage(){const qs=new URLSearchParams({limit:String(state.taskLimit),offset:String(state.taskPage*state.taskLimit)});if(state.taskStatus)qs.set('status',state.taskStatus);if(state.taskType)qs.set('type',state.taskType);const d=await api(`/api/v1/tasks?${qs.toString()}`);const pages=Math.max(1,Math.ceil(d.total/state.taskLimit));$('#content').innerHTML=window.head('后台任务','AI / OCR / ASR / 批量导入任务的状态、尝试次数、耗时、错误和恢复入口。',`<button class="btn" onclick="tasksPage()">刷新</button>`)+`<section class="panel"><div class="panel-body"><div class="searchbar"><div class="field"><label>状态筛选</label><select id="task-status" class="select"><option value="">全部</option>${['running','waiting_provider','failed','partial','succeeded','cancelled'].map(v=>`<option value="${v}" ${state.taskStatus===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>类型筛选</label><select id="task-type" class="select"><option value="">全部</option>${['evidence_extract','ocr','ocr_pdf','asr','batch_candidate_intake'].map(v=>`<option value="${v}" ${state.taskType===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="actions" style="align-self:end"><button class="btn primary" onclick="applyTaskFilters()">应用筛选</button></div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>任务</th><th>类型</th><th>状态</th><th>进度</th><th>尝试次数</th><th>耗时</th><th>结果 / 错误</th><th>创建</th><th></th></tr></thead><tbody>${d.tasks.length?d.tasks.map(x=>`<tr><td class="mono">${esc(x.task_id.slice(0,8))}…</td><td>${esc(x.type)}</td><td><span class="status ${window.statusClass(x.status)}">${esc(x.status)}</span></td><td>${x.progress_current}/${x.progress_total}</td><td>${x.attempt_count||0}</td><td>${x.duration_ms==null?'—':`${x.duration_ms} ms`}</td><td class="ellipsis">${esc(x.error_message||(Object.keys(x.result||{}).length?JSON.stringify(x.result):'—'))}</td><td>${new Date(x.created_at).toLocaleString()}</td><td class="right">${['failed','waiting_provider'].includes(x.status)&&['ocr','ocr_pdf','asr','evidence_extract'].includes(x.type)?`<button class="btn small primary" onclick="retryTask('${x.task_id}')">重试</button>`:''} ${!['succeeded','cancelled'].includes(x.status)?`<button class="btn small" onclick="cancelTask('${x.task_id}')">取消</button>`:''}</td></tr>`).join(''):'<tr><td colspan="9"><div class="empty"><strong>暂无符合条件的后台任务</strong>调整筛选条件，或执行 AI / OCR / ASR / 批量导入。</div></td></tr>'}</tbody></table></div><div class="actions" style="justify-content:flex-end;padding:12px"><button class="btn small" ${state.taskPage<=0?'disabled':''} onclick="taskPage(-1)">上一页</button><span class="subtle">第 ${state.taskPage+1} / ${pages} 页，共 ${d.total} 项</span><button class="btn small" ${(state.taskPage+1)>=pages?'disabled':''} onclick="taskPage(1)">下一页</button></div></section>`};window.applyTaskFilters=()=>{state.taskStatus=$('#task-status')?.value||'';state.taskType=$('#task-type')?.value||'';state.taskPage=0;tasksPage()};window.taskPage=delta=>{state.taskPage=Math.max(0,state.taskPage+delta);tasksPage()};window.retryTask=async id=>{try{const r=await api(`/api/v1/tasks/${id}/retry`,{method:'POST'});toast(`任务状态：${r.status}`);await tasksPage()}catch(e){toast(e.message,true)}};window.cancelTask=async id=>{await api(`/api/v1/tasks/${id}/cancel`,{method:'POST'});toast('任务已取消');await tasksPage()};
async function settingsPage(){const [p,b,d]=await Promise.all([api('/api/v1/settings/providers'),api('/api/v1/system/backups'),api('/api/v1/system/diagnostics')]);state.providers=p;const dbOk=d.database?.quick_check==='ok';const blobOk=(d.storage?.missing_source_blobs||0)===0;$('#content').innerHTML=window.head('系统设置','配置文本 AI、OCR、ASR，并管理本地备份、运行健康和诊断。')+`<div class="three">${[['text_ai','文本 AI','DeepSeek / OpenAI-compatible：JD、材料事实提取、复评辅助'],['ocr','OCR','扫描简历、图片、image-only PDF 文字识别'],['asr','ASR','电话筛选、面试录音与视频音轨转写']].map(([k,t,sub])=>providerCard(k,t,sub,p.profiles[k])).join('')}</div><div class="grid kpi" style="margin-top:16px"><div class="kpi-card"><div class="kpi-label">数据库健康</div><div class="kpi-value">${dbOk?'OK':'异常'}</div><div class="kpi-note">SQLite quick_check: ${esc(d.database?.quick_check||'unknown')}</div></div><div class="kpi-card"><div class="kpi-label">Blob 完整性</div><div class="kpi-value">${blobOk?'OK':d.storage.missing_source_blobs}</div><div class="kpi-note">${d.storage?.blob_files||0} 个文件 · ${((d.storage?.blob_bytes||0)/1024/1024).toFixed(1)} MB</div></div><div class="kpi-card"><div class="kpi-label">开放任务</div><div class="kpi-value">${d.tasks?.open||0}</div><div class="kpi-note">${esc(JSON.stringify(d.tasks?.by_status||{}))}</div></div><div class="kpi-card"><div class="kpi-label">数据目录</div><div class="kpi-value">${((d.storage?.data_bytes||0)/1024/1024).toFixed(1)} MB</div><div class="kpi-note">待恢复：${d.pending_restore?'是':'否'}</div></div></div><div class="two" style="margin-top:16px"><section class="panel"><div class="panel-head"><h2>备份与恢复</h2><button class="btn primary" onclick="createBackup()">创建一致性备份</button></div><div class="panel-body"><p class="subtle">恢复不会在运行中的数据库上覆盖文件。选择恢复后，会在下次启动、数据库打开前执行。</p><div id="backup-list">${b.backups.length?b.backups.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.filename)}</div><div class="quick-note">${(x.size_bytes/1024/1024).toFixed(2)} MB</div></div><div class="actions"><a class="btn small" href="/api/v1/system/backups/${encodeURIComponent(x.filename)}">下载</a><button class="btn small danger" onclick="scheduleRestore('${esc(x.filename)}')">下次启动恢复</button></div></div>`).join(''):'<div class="empty">暂无备份</div>'}</div></div></section><section class="panel"><div class="panel-head"><h2>运行诊断</h2><button class="btn" onclick="settingsPage()">刷新</button></div><div class="panel-body"><div class="quick-list"><div class="quick-item"><span>版本</span><strong>${esc(d.version)}</strong></div><div class="quick-item"><span>Schema</span><strong>${esc(d.schema_revision)}</strong></div><div class="quick-item"><span>项目 / 候选人 / Source / Claim</span><strong>${d.counts.projects} / ${d.counts.candidates} / ${d.counts.sources} / ${d.counts.claims}</strong></div></div><div class="divider"></div><div class="actions"><button class="btn" onclick='showDiagnostics(${JSON.stringify(JSON.stringify(d)).replace(/'/g,"&#39;")})'>查看完整诊断</button><a class="btn primary" href="/api/v1/system/diagnostics/export" download>导出隐私安全诊断包</a></div></div></section></div>`}
function providerCard(k,title,sub,p){return `<div class="provider-card"><div class="provider-title"><div><h3>${title}</h3><div class="provider-sub">${sub}</div></div><span class="status ${p.api_key_configured?'good':'warn'}">${p.api_key_configured?'Key 已配置':'未配置 Key'}</span></div><div class="field"><label>Provider</label><select id="p-${k}-type" class="select"><option value="deepseek" ${p.provider_type==='deepseek'?'selected':''}>DeepSeek</option><option value="openai_compatible" ${p.provider_type==='openai_compatible'?'selected':''}>OpenAI-compatible</option></select></div><div class="field" style="margin-top:8px"><label>模型</label><input id="p-${k}-model" class="input" value="${esc(p.model)}"></div><div class="field" style="margin-top:8px"><label>Base URL</label><input id="p-${k}-url" class="input" value="${esc(p.base_url)}"></div><div class="field" style="margin-top:8px"><label>API Key（留空表示不修改）</label><input id="p-${k}-key" class="input" type="password" autocomplete="off"></div><div class="actions" style="margin-top:12px"><button class="btn primary" onclick="saveProvider('${k}')">保存</button><button class="btn" onclick="testProvider('${k}')">真实能力测试</button></div></div>`}
window.saveProvider=async k=>{try{const key=$(`#p-${k}-key`).value;const body={provider_type:$(`#p-${k}-type`).value,model:$(`#p-${k}-model`).value,base_url:$(`#p-${k}-url`).value,reasoning_effort:'medium'};if(key)body.api_key=key;await api(`/api/v1/settings/providers/${k}`,{method:'PATCH',body:JSON.stringify(body)});toast(`${k} 配置已保存`);await settingsPage()}catch(e){toast(e.message,true)}};window.testProvider=async k=>{try{toast('正在执行真实能力测试…');const r=await api(`/api/v1/settings/providers/${k}/test`,{method:'POST'});toast(`${k} ${r.model} 测试通过`)}catch(e){toast(e.message,true)}};
window.createBackup=async()=>{try{const r=await api('/api/v1/system/backups',{method:'POST'});toast(`备份已创建：${r.filename}`);await settingsPage()}catch(e){toast(e.message,true)}};window.scheduleRestore=async name=>{if(!confirm(`计划在下次启动恢复 ${name}？`))return;try{await api(`/api/v1/system/backups/${encodeURIComponent(name)}/restore`,{method:'POST'});toast('已计划恢复，请关闭工作台并重新启动后生效')}catch(e){toast(e.message,true)}};window.showDiagnostics=s=>modal('完整诊断',`<div class="codebox">${esc(JSON.stringify(JSON.parse(s),null,2))}</div>`);
